import {escapeHtml as h,number} from './domain.js';
import {badge} from './art.js';
export {technologyHelp} from './research-help.js';
export const researchBranches={infrastructure:['Navigation & énergie','⌁','#4cc9ff'],intelligence:['Renseignement','◈','#a98cf5'],exploitation:['Exploitation','▥','#7fd36a'],warfare:['Art de la guerre','✦','#ff9a6b'],scanning:['Reconnaissance','◎','#7fb4ff']};
const duration=n=>{const hours=Number(n)||0;return hours>=24?`${Math.floor(hours/24)} j${hours%24?` ${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(hours%24)} h`:''}`:`${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(hours)} h`;};
const date=v=>new Date(v).toLocaleString('fr-FR',{dateStyle:'short',timeStyle:'short'});
const errorBox='<p class="form-error" role="alert" hidden></p>';
export function researchAvailability(c,data,treasury,planetId){const job=(data.research_jobs||[]).find(j=>j.key===c.key),maxed=Number(c.level)>=Number(c.max_level),lab=(c.eligible_planets||[]).find(p=>p.id===planetId),prerequisites=!!c.prerequisites_met,ready=!!(!maxed&&!job&&prerequisites&&lab&&!lab.busy&&Number(treasury)>=Number(c.next_cost));return {job,maxed,lab,ready,status:maxed?'researched':job?'researching':prerequisites?'available':'locked',reason:maxed?'Tous les niveaux sont acquis.':job?'Cette technologie est déjà en recherche.':!prerequisites?'Prérequis à compléter.':!lab?'Ce laboratoire est incompatible avec cette recherche.':lab.busy?'Une recherche occupe déjà ce laboratoire.':Number(treasury)<Number(c.next_cost)?'Trésorerie insuffisante.':'Laboratoire libre et compatible.'};}
export function researchGraphLayout(catalog,branch){
 const nodes=catalog.filter(c=>c.branch===branch),byKey=new Map(nodes.map(c=>[c.key,c])),ordered=[],visited=new Set();
 const visit=(c,path=new Set())=>{if(visited.has(c.key)||path.has(c.key))return;const next=new Set(path).add(c.key);for(const r of c.requires||[]){const parent=byKey.get(r.key);if(parent)visit(parent,next);}visited.add(c.key);ordered.push(c);};for(const c of nodes)visit(c);
 const rows=new Map(),positions=new Map();for(const c of ordered){let col=Math.max(0,...(c.requires||[]).filter(r=>positions.has(r.key)).map(r=>(positions.get(r.key).x-24)/278+1));while((rows.get(col)||0)>=3)col++;const row=rows.get(col)||0;rows.set(col,row+1);positions.set(c.key,{x:24+col*278,y:24+row*176});}

 return {nodes,positions,width:Math.max(600,...[...positions.values()].map(p=>p.x+264)),height:Math.max(400,...[...positions.values()].map(p=>p.y+164))};
}
function researchForm(c,world,ready,label='Lancer la recherche'){return `<form data-technology="research"><input type="hidden" name="technology" value="${h(c.key)}"><input type="hidden" name="planet_id" value="${h(world?.id||'')}"><input type="hidden" name="expected_level" value="${Number(c.level)+1}">${errorBox}<button class="primary" type="submit" ${ready?'':'disabled'}>${label}</button></form>`;}
function levelEffect(key,n){if(key==='teleport_improved')return ` · ${[2,3,5][n-1]} soldats / énergie`;if(key==='energy_magma')return ` · réserve jusqu’à ${[25,50,75,100][n-1]}`;if(key==='travel')return ` · durée ×${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(.85**n)}`;return '';}
function detailPanel(c,data,treasury,world){if(!c)return '<aside class="tech-detail"><p>Aucune technologie dans cette branche.</p></aside>';const a=researchAvailability(c,data,treasury,world?.id),branch=researchBranches[c.branch],end=Date.now()+Number(c.next_hours)*3600000,unlocks=data.catalog.filter(x=>(x.requires||[]).some(r=>r.key===c.key));return `<aside class="tech-detail" aria-label="Détail de la technologie"><span class="eyebrow">SÉLECTION · ${h(branch?.[0]||'Recherche')}</span><h2>${h(c.name)}</h2><p class="tech-detail-effect">${h(c.effect)}</p><ol class="tech-level-ladder">${Array.from({length:c.max_level},(_,i)=>i+1).map(n=>`<li class="${n<=c.level?'done':n===Number(c.level)+1?'next':''}"><i>${n<=c.level?'✓':n}</i><span>Niveau ${n}${levelEffect(c.key,n)}</span><small>${n<=c.level?'acquis':n===Number(c.level)+1?'prochain':''}</small></li>`).join('')}</ol><section class="tech-detail-prerequisites"><h3>Prérequis</h3>${(c.requires||[]).length?c.requires.map(r=>{const parent=data.catalog.find(x=>x.key===r.key),met=parent?.level>=r.level;return `<button class="tech-prerequisite ${met?'met':''}" data-research-jump="${h(r.key)}">${met?'✓':'○'} ${h(parent?.name||r.key)}${r.level>1?` · N${r.level}`:''}</button>`;}).join(''):'<span>Aucun prérequis.</span>'}</section>${unlocks.length?`<section class="tech-detail-unlocks"><h3>Débloque ensuite</h3>${unlocks.map(x=>`<button data-research-jump="${h(x.key)}">${h(x.name)}<small>${h(researchBranches[x.branch]?.[0]||'')}</small></button>`).join('')}</section>`:''}<section class="tech-laboratory"><h3>Laboratoire</h3><b>${world?badge('race',world.race)+badge('resource',world.resource)+h(world.name):'Aucune planète'}</b><p class="${a.ready?'ready':''}">${h(a.reason)}</p>${!a.lab&&!a.maxed?`<button class="text-button" data-research-lab-focus>Choisir un laboratoire compatible</button>`:''}</section>${a.job?`<div class="tech-selected-job"><strong>Recherche en cours</strong><p>${h(a.job.planet)} · fin ${date(a.job.finishes_at)}</p><form data-technology="research_cancel"><input type="hidden" name="job_id" value="${h(a.job.id)}"><button class="secondary" type="submit">Annuler la recherche</button>${errorBox}</form></div>`:a.maxed?'<strong class="tech-detail-owned">✓ Technologie acquise</strong>':`<div class="tech-investment"><div><strong>${number(c.next_cost)} Þ</strong><small>Durée ${duration(c.next_hours)}</small><small>Fin estimée : ${date(end)}</small></div><span>Trésorerie<b>${number(treasury)} Þ</b></span></div>${researchForm(c,world,a.ready,world?'Lancer sur '+h(world.name):'Choisir un laboratoire')}`}</aside>`;}
export function researchTreeView(data,treasury,selectedId,ui={}){
 const catalog=data.catalog||[],jobs=data.research_jobs||[],worlds=data.planets||[],world=worlds.find(p=>p.id===selectedId)||worlds[0],busy=new Set(jobs.map(j=>j.planet_id)),branch=researchBranches[ui.branch]?ui.branch:'infrastructure',layout=researchGraphLayout(catalog,branch),selected=catalog.find(c=>c.key===ui.selected&&c.branch===branch)||layout.nodes.find(c=>researchAvailability(c,data,treasury,world?.id).ready)||layout.nodes[0],filter=ui.filter||'all',acquired=catalog.filter(c=>c.level>0).length,ready=catalog.filter(c=>researchAvailability(c,data,treasury,world?.id).ready);
 const branchButton=([key,[name,glyph,color]])=>{const rows=catalog.filter(c=>c.branch===key),done=rows.filter(c=>c.level>0).length,n=rows.filter(c=>researchAvailability(c,data,treasury,world?.id).ready).length;return `<button class="tech-branch-choice ${key===branch?'selected':''}" data-research-filter="${key}" aria-pressed="${key===branch}" style="--tech-color:${color}"><i>${glyph}</i><span><b>${name}</b><progress value="${done}" max="${rows.length||1}" aria-label="Technologies débloquées : ${h(name)}"></progress></span><span class="tech-branch-count">${done}<small>/${rows.length}</small>${n?`<em>${n} dispo</em>`:''}</span></button>`;};
 const node=c=>{const a=researchAvailability(c,data,treasury,world?.id),pos=layout.positions.get(c.key),cross=catalog.filter(x=>x.branch!==branch&&(x.requires||[]).some(r=>r.key===c.key)),matched=filter==='all'||filter==='available'&&a.ready||filter==='researched'&&c.level>0||filter==='locked'&&a.status==='locked',state=a.maxed?'Acquise':a.job?'En cours':a.status==='locked'?'Verrouillée':!a.lab?'Labo requis':a.lab.busy?'Labo occupé':Number(treasury)<Number(c.next_cost)?'À financer':c.level?'Améliorable':'Disponible';return `<article id="research-${h(c.key)}" class="tech-timeline-node research-node ${h(c.branch)} ${a.status} ${c.key===selected?.key?'selected':''} ${matched?'':'muted-node'}" style="left:${pos.x}px;top:${pos.y}px"><button class="tech-node-select" data-research-select="${h(c.key)}" aria-pressed="${c.key===selected?.key}" title="${h(a.reason)}"><span class="tech-node-heading">${c.race?badge('race',c.race):c.resource?badge('resource',c.resource):`<i>${researchBranches[branch][1]}</i>`}<strong>${h(c.name)}</strong></span><span class="tech-node-state"><b>${state}</b><small>${c.level?`N${c.level}${!a.maxed&&!a.job?' → '+(Number(c.level)+1):''}`:(c.requires||[]).length&&!c.prerequisites_met?`${c.requires.length} prérequis`:'Niveau 1'}</small></span><span class="tech-node-price">${a.maxed?'<b>✓ Acquise</b>':a.job?`<small>${h(a.job.planet)} · ${date(a.job.finishes_at)}</small>`:`<b>${number(c.next_cost)} Þ</b><small>${duration(c.next_hours)}</small>`}</span></button>${cross.length?`<button class="tech-cross-link" data-research-jump="${h(cross[0].key)}">${cross.length} dépendance${cross.length>1?'s':''} vers d’autres branches</button>`:''}</article>`;};
 const edges=layout.nodes.flatMap(c=>(c.requires||[]).filter(r=>layout.positions.has(r.key)).map(r=>{const a=layout.positions.get(r.key),b=layout.positions.get(c.key),met=(catalog.find(x=>x.key===r.key)?.level||0)>=r.level;return `<path class="${met?'met':'locked'}" d="M${a.x+240} ${a.y+65} C${a.x+260} ${a.y+65},${b.x-20} ${b.y+65},${b.x} ${b.y+65}"/>${r.level>1?`<text x="${a.x+245}" y="${a.y+55}">N${r.level} requis</text>`:''}`;})).join('');
 return `<section class="research-tree research-tree-v2"><div class="tech-topline"><div class="research-toolbar"><label>Laboratoire<select id="research-planet">${worlds.map(p=>`<option value="${h(p.id)}" ${p.id===world?.id?'selected':''}>${h(p.name)} · ${busy.has(p.id)?'occupé':'libre'}</option>`).join('')}</select></label><div class="research-lab-traits">${world?badge('race',world.race)+badge('resource',world.resource):''}<strong>${Math.max(0,worlds.length-busy.size)}<small>libre${worlds.length-busy.size>1?'s':''}</small></strong></div></div><div class="tech-active-jobs">${jobs.length?jobs.map(j=>{const progress=Math.max(0,Math.min(100,(Date.now()-new Date(j.started_at))/(new Date(j.finishes_at)-new Date(j.started_at))*100));return `<button class="tech-active-job" data-research-jump="${h(j.key)}"><span><small>EN COURS · ${h(j.planet)}</small><strong>${h(j.name)}${j.level>1?' · N'+j.level:''}</strong><progress value="${progress}" max="100" aria-label="Progression de la recherche"></progress></span><time datetime="${h(j.finishes_at)}">${date(j.finishes_at)}</time></button>`;}).join(''):'<div class="tech-no-job"><span>RECHERCHE</span><strong>Vos laboratoires sont prêts.</strong><small>Sélectionnez une technologie pour lancer un projet.</small></div>'}</div></div><div class="tech-workspace"><aside class="tech-branch-panel"><div class="tech-total"><span class="eyebrow">TECHNOLOGIES DÉBLOQUÉES</span><strong>${acquired}<small> / ${catalog.length}</small></strong><progress value="${acquired}" max="${catalog.length||1}" aria-label="Progression technologique globale"></progress></div><nav aria-label="Branches technologiques">${Object.entries(researchBranches).map(branchButton).join('')}</nav><div class="tech-status-filters"><span>Mettre en évidence</span>${[['all','Tout'],['available','Disponibles'],['researched','Acquises'],['locked','Verrouillées']].map(([key,title])=>`<button data-tech-status="${key}" aria-pressed="${filter===key}">${title}</button>`).join('')}</div></aside><div class="tech-frieze-column"><header class="tech-frieze-heading"><div><i style="color:${researchBranches[branch][2]}">${researchBranches[branch][1]}</i><h2>${researchBranches[branch][0]}</h2></div><span>${layout.nodes.filter(c=>c.level>0).length} / ${layout.nodes.length} débloquées</span></header><div class="tech-frieze-navigation"><span>Les liens indiquent les prérequis.</span><div><button data-tech-pan="previous" aria-label="Défiler vers la gauche">‹</button><button data-tech-pan="next" aria-label="Défiler vers la droite">›</button><button data-tech-pan="selected" aria-label="Centrer la sélection">Centrer</button></div></div><div class="tech-frieze-scroll" tabindex="0" role="region" aria-label="Arbre technologique défilant horizontalement"><div class="tech-frieze-canvas" style="width:${layout.width}px;height:${layout.height}px;--tech-color:${researchBranches[branch][2]}"><svg width="${layout.width}" height="${layout.height}" aria-hidden="true">${edges}</svg>${layout.nodes.map(node).join('')}</div></div><section class="tech-ready-section"><div class="tech-ready-heading"><span class="eyebrow">PRÊTES À LANCER${world?' SUR '+h(world.name.toUpperCase()):''}</span><span>${ready.length} recherche${ready.length>1?'s':''}</span></div><div class="tech-ready-list">${ready.length?ready.map(c=>`<article style="--tech-color:${researchBranches[c.branch]?.[2]}"><button class="tech-quick-select" data-research-jump="${h(c.key)}">${h(c.name)}</button><div><span><b>${number(c.next_cost)} Þ</b><small>${duration(c.next_hours)}</small></span>${researchForm(c,world,true,'Lancer')}</div></article>`).join(''):'<p>Aucune recherche prête dans ce laboratoire avec la trésorerie actuelle.</p>'}</div></section></div>${detailPanel(selected,data,treasury,world)}</div></section>`;
}
export function bindResearchTree(state,render){
 const root=document.querySelector('.research-tree-v2');if(!root)return;const ui=state.researchUI||={branch:'infrastructure',filter:'all',scroll:{}};ui.scroll||={};
 const scroll=root.querySelector('.tech-frieze-scroll'),branch=ui.branch||'infrastructure';if(ui.scroll[branch]){scroll.scrollLeft=ui.scroll[branch].left;scroll.scrollTop=ui.scroll[branch].top;}scroll.addEventListener('scroll',()=>{ui.scroll[ui.branch||'infrastructure']={left:scroll.scrollLeft,top:scroll.scrollTop};},{passive:true});
 const select=key=>{const c=state.technologies?.catalog?.find(c=>c.key===key);if(!c)return;ui.branch=c.branch;ui.selected=key;ui.center=true;render();};
 root.querySelector('#research-planet')?.addEventListener('change',event=>{state.researchPlanet=event.target.value;render();});
 root.querySelectorAll('[data-research-filter]').forEach(button=>button.onclick=()=>{ui.branch=button.dataset.researchFilter;ui.filter='all';render();});
 root.querySelectorAll('[data-research-select]').forEach(button=>button.onclick=()=>select(button.dataset.researchSelect));
 root.querySelectorAll('[data-research-jump]').forEach(button=>button.onclick=()=>select(button.dataset.researchJump));
 root.querySelectorAll('[data-tech-status]').forEach(button=>button.onclick=()=>{ui.filter=button.dataset.techStatus;render();});
 const center=()=>{const node=root.querySelector('.tech-timeline-node.selected');if(node)scroll.scrollTo({left:Math.max(0,node.offsetLeft-(scroll.clientWidth-node.offsetWidth)/2),top:Math.max(0,node.offsetTop-(scroll.clientHeight-node.offsetHeight)/2),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});};
 root.querySelectorAll('[data-tech-pan]').forEach(button=>button.onclick=()=>button.dataset.techPan==='selected'?center():scroll.scrollBy({left:(button.dataset.techPan==='previous'?-1:1)*Math.max(260,scroll.clientWidth*.75),behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));
 scroll.addEventListener('keydown',event=>{if(event.target!==scroll||!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();if(event.key==='Home'||event.key==='End')scroll.scrollTo({left:event.key==='Home'?0:scroll.scrollWidth});else scroll.scrollBy({left:event.key==='ArrowLeft'?-278:278});});
 root.querySelector('[data-research-lab-focus]')?.addEventListener('click',()=>root.querySelector('#research-planet').focus());
 if(ui.center){ui.center=false;center();}
}
